import{_ as s,o as e,c as n,a4 as i}from"./chunks/framework.BRzJ4ijD.js";const k=JSON.parse('{"title":"inode、dentry、page cache","description":"","frontmatter":{},"headers":[],"relativePath":"os/fs/inode-pagecache.md","filePath":"os/fs/inode-pagecache.md","lastUpdated":1788475713000}'),t={name:"os/fs/inode-pagecache.md"};function p(c,a,l,d,o,r){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="inode、dentry、page-cache" tabindex="-1">inode、dentry、page cache <a class="header-anchor" href="#inode、dentry、page-cache" aria-label="Permalink to &quot;inode、dentry、page cache&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>你说 <code>cat /etc/passwd</code>，看似&quot;打开一个文件然后读字节&quot;。实际内核做了五层抽象:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>路径 /etc/passwd</span></span>
<span class="line"><span>   ↓ (dentry 树解析)</span></span>
<span class="line"><span>inode 号 + fs 元信息</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>磁盘 block 列表 (extent / direct / indirect)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>page cache (一次 page 4 KB)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>块层 + IO 调度</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>NVMe 提交 queue → DRAM 落块</span></span></code></pre></div><p>每层都是一个 cache, 每层都各有失效模式. 这一章把这套链路拆开, 让你看清 <code>open + read</code> 在 OS 内部到底是怎么发生的——同时也解释为什么 PostgreSQL / InnoDB / Rocks 这些系统都坚持自己再做一遍 IO 层.</p><h2 id="_1-dentry-路径字符串看到的虚拟树" tabindex="-1">1. dentry: 路径字符串看到的虚拟树 <a class="header-anchor" href="#_1-dentry-路径字符串看到的虚拟树" aria-label="Permalink to &quot;1. dentry: 路径字符串看到的虚拟树&quot;">​</a></h2><p>当你 <code>cat /etc/passwd</code> 内核要先做 <strong>path resolution</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/   →  根 dir inode 1</span></span>
<span class="line"><span>etc →  在根 dir 找 &quot;etc&quot; 这一项</span></span>
<span class="line"><span>       这一项指向下一层 dentry</span></span>
<span class="line"><span>passwd → 在 etc dir 找 &quot;passwd&quot; 这项</span></span>
<span class="line"><span>       拿到 final inode</span></span></code></pre></div><p>每一层访问都是一次目录扫描 (实际是个 hash/遍历查找). preload 内存里维护 dentry cache (dcache), 命中即命中.</p><p><strong>dcache 是 OS 层 &quot;路径 → inode&quot; 的缓存</strong>. 内核启动后大部分系统的 <code>/usr/bin</code> 等热目录可达 dcache 100% 命中.</p><h2 id="_2-inode-一个文件的-metadata" tabindex="-1">2. inode: 一个文件的 metadata <a class="header-anchor" href="#_2-inode-一个文件的-metadata" aria-label="Permalink to &quot;2. inode: 一个文件的 metadata&quot;">​</a></h2><p>inode 装着:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文件大小</span></span>
<span class="line"><span>所有者 + 权限</span></span>
<span class="line"><span>atime / mtime / ctime</span></span>
<span class="line"><span>文件数据 block 列表 (extent 或 direct + indirect)</span></span>
<span class="line"><span>文件类型 (regular / dir / link / device / FIFO)</span></span></code></pre></div><p><strong>注意 inode 不带文件名</strong>——文件名是它在父目录这条 dentry 的属性. 一份 inode 可被多个 dentry 指 (hardlink), 即一个文件可以多个文件名, 但 inode 本身唯一.</p><p>读 inode 也走过 VFS 层后到具体 fs, 在 ext4 上是 <code>ext4_inode</code> 结构, 字段 packed, 256 字节起步, 大文件可扩展.</p><h2 id="_3-extent-vs-indirect-block-怎么描述-一个文件的所有数据块" tabindex="-1">3. extent vs indirect block: 怎么描述&quot;一个文件的所有数据块&quot; <a class="header-anchor" href="#_3-extent-vs-indirect-block-怎么描述-一个文件的所有数据块" aria-label="Permalink to &quot;3. extent vs indirect block: 怎么描述&quot;一个文件的所有数据块&quot;&quot;">​</a></h2><p>历史方案是 BSD 早期用 <strong>direct block + indirect block + double indirect + triple indirect</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inode 前 12 个 block pointer 直接给前 12 × 4 KB = 48 KB;</span></span>
<span class="line"><span>第 13 个 pointer → 一块装 1024 pointer → 1024 × 4 = 4 MB;</span></span>
<span class="line"><span>第 14 个 pointer → 一块装 1024 个 pointer → 每 pointer 又指向装 1024 pointer 的块;</span></span>
<span class="line"><span>第 15 个 → 4 GB;</span></span></code></pre></div><p>听起来文艺但不工程友好 —— 大文件一次访问多级寻址 + cache miss.</p><p><strong>现代文件系统改用 extent</strong>: 一个 extent 直接表示 <code>[起始 block, 长度 L blocks]</code>. ext4 一个 inode 装内嵌 4 个 extent, 一个 extent 默认最大 32 KB (现代改进后 extent tree 可以扩展). XFS 用 B+ 树 extent.</p><p>extent 的好处:</p><ul><li>顺序文件 metadata 极小 (1 GB 文件 = 一个 extent entry);</li><li>顺序 IO 友好 (磁盘一次 sequential read);</li><li>大文件碎片化 metadata 节省 cookie.</li></ul><p><strong>这是 DSA 中 B+ 树 + 顺序物理化 在 OS 文件系统层的同构</strong>.</p><h2 id="_4-page-cache-把-读过的页-留在-dram" tabindex="-1">4. page cache: 把&quot;读过的页&quot; 留在 DRAM <a class="header-anchor" href="#_4-page-cache-把-读过的页-留在-dram" aria-label="Permalink to &quot;4. page cache: 把&quot;读过的页&quot; 留在 DRAM&quot;">​</a></h2><p>文件 IO 的真实路径不是 <code>read → disk</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>read(fd, buf, n)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>explicit_filemap_read → page cache 命中 →</span></span>
<span class="line"><span>   ↓                                ↓</span></span>
<span class="line"><span>命中就 memcpy 到 buf            miss →</span></span>
<span class="line"><span>                              submit_bio → 块层 / NVMe</span></span>
<span class="line"><span>                              data 拉进 page cache</span></span>
<span class="line"><span>                              再 memcpy 到 user buf</span></span></code></pre></div><p><code>read</code> 总是先看 page cache, <code>mmap</code> 是更高级别坐进 page cache 让用户空间零拷贝访问.</p><p><strong>page cache 是 OS 层的&quot;通用 read cache&quot;</strong>, 对所有进程间共享——如果两个进程同时 cat 同一个文件, 同一个 page cache 被 reused.</p><h2 id="_5-dirty-page-与-writeback" tabindex="-1">5. dirty page 与 writeback <a class="header-anchor" href="#_5-dirty-page-与-writeback" aria-label="Permalink to &quot;5. dirty page 与 writeback&quot;">​</a></h2><p>写路径:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>write(fd, buf, n)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>page cache 上写 (与 read 反过来, 先看命中)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>mark dirty + 设置 dirty 标记位</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>  pthread_async + writeback thread 慢慢 submit_bio 来刷盘</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>disk 完成, 清 dirty 标记</span></span></code></pre></div><p><code>write</code> 在 99% 情况下不立刻写盘. 这是 OS 优化的核心: 把 write-burst 缓冲起来 + 顺序刷盘 + 由 IO 调度合并相邻 page.</p><p>但要持久化, 用户必须 <code>fsync(fd)</code> —— <strong>强制把 dirty 同步刷盘并等 disk ACK</strong>. fsync 之前的数据<strong>可能在断电 / panic 中丢</strong>, 这是 crash consistency 的核心题.</p><h2 id="_6-文件-io-怎么测性能" tabindex="-1">6. 文件 IO 怎么测性能 <a class="header-anchor" href="#_6-文件-io-怎么测性能" aria-label="Permalink to &quot;6. 文件 IO 怎么测性能&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 系统 cache 命中</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cat /etc/passwd </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /dev/null          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 几百 μs</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 强制读盘 + Drop cache</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/sys/vm/drop_caches</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cat large_file </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /dev/null           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 看盘速度</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 用 fio 做 raw benchmark</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name=test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filename=/tmp/a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rw=randread</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bs=4k</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --size=1G</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --iodepth=8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --numjobs=8</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 看 page cache 占用大小</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">free</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vmstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div><h2 id="_7-多语言-多运行时" tabindex="-1">7. 多语言 / 多运行时 <a class="header-anchor" href="#_7-多语言-多运行时" aria-label="Permalink to &quot;7. 多语言 / 多运行时&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语言</th><th>默认 IO 路径</th><th>优势 / 坑</th></tr></thead><tbody><tr><td>C <code>read/write</code></td><td>系统调用 + page cache</td><td>取决于 fsync</td></tr><tr><td>Go <code>os.File.Read</code></td><td>同上 + goroutine 调度 不阻塞 GMP</td><td><code>GOMAXPROCS</code> 满时阻塞会 M 扩</td></tr><tr><td>Rust <code>File::read</code></td><td><code>libc</code> wrapper, 内 <code>read</code></td><td>async 用 <code>tokio::fs</code> 走 epoll + thread pool</td></tr><tr><td>Java <code>InputStreamReader</code></td><td>JVM 内 heap buffer + page cache</td><td>双层 buffer 有时浪费</td></tr><tr><td>Python <code>open().read</code></td><td>C InputStreamReader 流式 buffer</td><td>写大文件建议 <code>buffering</code> 调大</td></tr></tbody></table><p>各语言 IO 接口都 wraps 系统 syscall, 抽象同一, 仅 syntactic 差异. <strong>真正工程上 IO 性能差别主要看 cache 是否被正确使用 + fsync 频率</strong>.</p><h2 id="_8-pg-innodb-rocks-的-自己再写-io" tabindex="-1">8. PG / InnoDB / Rocks 的&quot;自己再写 IO&quot; <a class="header-anchor" href="#_8-pg-innodb-rocks-的-自己再写-io" aria-label="Permalink to &quot;8. PG / InnoDB / Rocks 的&quot;自己再写 IO&quot;&quot;">​</a></h2><p>主流数据库 (PG / MySQL / MongoDB / RocksDB) <strong>绕过操作系统 page cache + 自己做缓存管理</strong>:</p><ul><li>内 buffer pool 是 OS page cache 的平行物, 但能精确控制 LRU + 大小 + writeback;</li><li>使用 <code>O_DIRECT</code> flag (下一章详谈) 让 IO 不进 page cache;</li><li>自己做 pread + WAL + checksum.</li></ul><p>为什么? OS page cache 弱在<strong>多线程 + 大内存 + 多 workload 共享机器时不可预期</strong>. 自家 buffer pool 能控 : 哪个 thread 等谁、 cache hit 高 / 低、flush 时频率.</p><h2 id="_9-i-size-i-blocks-dense-sparse-file" tabindex="-1">9. i_size + i_blocks / dense sparse file <a class="header-anchor" href="#_9-i-size-i-blocks-dense-sparse-file" aria-label="Permalink to &quot;9. i_size + i_blocks / dense sparse file&quot;">​</a></h2><p>inode 的 <code>i_sb</code> (super block) 信息中含 <code>i_blocks</code> (used blocks count, 1 block = 512B). Linux <code>du -h</code> 用 <code>i_blocks × 512</code> 实际盘占用, 而 <code>ls -l</code> 用 <code>i_size</code> 逻辑大小. 这两者差距来自 sparse file 不一定真占用 block. mkfile 输出 50 GB sparse 文件 = 0 i_blocks, 但 i_size = 50 GB.</p><p><code>fallocate --dig</code> 通过 fallocate syscall 让 fs 提前置位 extent 但不实际写入 0, 当 metadata-first allocator, 极适合&quot;预占大文件 + 慢慢填充&quot;. 不预先 fallocate 大文件, 等 first write 时 fs 才动态分 extent, 在 high perf IO 场景上要 fallocate + O_DIRECT.</p><h2 id="_10-这一章带走的东西" tabindex="-1">10. 这一章带走的东西 <a class="header-anchor" href="#_10-这一章带走的东西" aria-label="Permalink to &quot;10. 这一章带走的东西&quot;">​</a></h2><ul><li><code>open + read</code> 实际穿五层 VFS/dentry/inode/page cache/block layer;</li><li>extent 模型是 indirect block 的工程演进 (少 metadata + 友 cache);</li><li>page cache 是不分进程共享的 read cache;</li><li>write 默认仅写 page cache, fsync 才保证持久化;</li><li>数据库普遍走 O_DIRECT 绕 page cache, 自己实现 buffer pool.</li></ul><p>下一节 → <a href="./filesystems">ext4 / XFS / Btrfs 设计差异</a></p>`,48)])])}const g=s(t,[["render",p]]);export{k as __pageData,g as default};
